"""Server-rendered shell and browser updater for the e-Voice VPS dashboard."""

# ruff: noqa: E501

from __future__ import annotations


def dashboard_panel() -> str:
    return r"""
<style>
.vps-shell{margin-top:18px;--line:#465158;--panel:#171d20;--panel2:#20282c;--cyan:#55d6e8;--green:#36d399;--yellow:#fbbd23;--red:#f87272}.vps-hero,.vps-panel,.vps-metric{background:linear-gradient(145deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:14px}.vps-hero{padding:20px;display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}.vps-eyebrow{color:var(--cyan);font-size:12px;font-weight:900;letter-spacing:.14em}.vps-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin-top:12px}.vps-metric,.vps-panel{padding:17px}.vps-value{font-size:28px;font-weight:850;margin:4px 0}.vps-progress{height:7px;background:#394348;border-radius:10px;overflow:hidden}.vps-progress span{height:100%;display:block;background:var(--cyan);transition:width .3s}.vps-columns{display:grid;grid-template-columns:1.35fr 1fr;gap:12px;margin-top:12px}.vps-row{display:flex;justify-content:space-between;gap:12px;padding:11px 0;border-bottom:1px solid var(--line)}.vps-row:last-child{border:0}.vps-badge{padding:4px 8px;border-radius:99px;font-size:11px;font-weight:800;text-transform:uppercase}.vps-good{color:var(--green)}.vps-warning{color:var(--yellow)}.vps-critical{color:var(--red)}.vps-badge.vps-good{background:#173d35}.vps-badge.vps-warning{background:#483b16}.vps-badge.vps-critical{background:#4b2024}.vps-info{background:#111719;border:1px solid var(--line);border-radius:10px;padding:13px}.vps-alert{border-left:3px solid var(--yellow);padding:10px;background:#25231b;margin-top:8px}.vps-alert.critical{border-color:var(--red)}#vpsMap{height:410px;border:1px solid var(--line);border-radius:10px;background:#111719}.vps-map-marker{display:flex;align-items:center;justify-content:center;border:2px solid white;border-radius:50%;background:#ef4444;color:white;font-size:10px;font-weight:900}.vps-map-marker.accepted{background:#38bdf8}.vps-table{overflow:auto}.vps-table table{margin:0;box-shadow:none}.vps-select{width:auto;background:#111;color:#fff;border-color:var(--cyan)}@media(max-width:900px){.vps-columns{grid-template-columns:1fr}#vpsMap{height:330px}}
</style>
<section class="vps-shell" aria-label="Monitoraggio VPS e-Voice">
 <div class="vps-hero"><div><div class="vps-eyebrow">EKONEX CLOUD VOICE · CONTROL CENTER</div><h2>Stato VPS</h2><div class="muted" id="vpsHost">Connessione al sistema...</div></div><div><b id="vpsHealth">Verifica in corso</b><div class="muted" id="vpsUpdated">—</div></div></div>
 <div class="vps-grid">
  <div class="vps-metric"><div class="muted">CPU</div><div class="vps-value" id="vpsCpu">—</div><div class="vps-progress"><span id="vpsCpuBar"></span></div><small class="muted" id="vpsCpuMeta">—</small></div>
  <div class="vps-metric"><div class="muted">Memoria</div><div class="vps-value" id="vpsRam">—</div><div class="vps-progress"><span id="vpsRamBar"></span></div><small class="muted" id="vpsRamMeta">—</small></div>
  <div class="vps-metric"><div class="muted">Disco</div><div class="vps-value" id="vpsDisk">—</div><div class="vps-progress"><span id="vpsDiskBar"></span></div><small class="muted" id="vpsDiskMeta">—</small></div>
  <div class="vps-metric"><div class="muted">Uptime</div><div class="vps-value" id="vpsUptime">—</div><small class="muted" id="vpsNetwork">—</small></div>
 </div>
 <div class="vps-columns"><div class="vps-panel"><h3>Servizi principali</h3><div id="vpsServices"></div></div><div class="vps-panel"><h3>Problemi e avvisi</h3><div id="vpsAlerts"></div></div></div>
 <div class="vps-columns"><div class="vps-panel"><h3>Servizi web e certificati</h3><div class="vps-grid" id="vpsWeb"></div></div><div class="vps-panel"><h3>Sicurezza VPS</h3><div class="vps-grid" id="vpsSecurity"></div></div></div>
 <div class="vps-columns"><div class="vps-panel"><div class="vps-row"><h3>Storico prestazioni</h3><select class="vps-select" id="vpsHistoryRange"><option value="1">1 ora</option><option value="24" selected>24 ore</option><option value="168">7 giorni</option><option value="720">30 giorni</option></select></div><canvas id="vpsHistoryChart" height="125"></canvas><div class="muted" id="vpsHistoryEmpty"></div></div><div class="vps-panel"><h3>Backup</h3><div class="vps-grid" id="vpsBackup"></div><h3>Inventario e versioni</h3><div class="vps-grid" id="vpsInventory"></div><h3>Incidenti recenti</h3><div id="vpsIncidents"></div></div></div>
 <div class="vps-panel" style="margin-top:12px"><div class="vps-row"><div><h3>Mappa mondiale connessioni</h3><small class="muted">Posizione GeoIP approssimativa degli accessi autorizzati e rifiutati.</small></div><select class="vps-select" id="vpsSecurityRange"><option value="24">24 ore</option><option value="168" selected>7 giorni</option><option value="720">30 giorni</option></select></div><div id="vpsMap"></div><div class="muted" id="vpsMapMeta"></div></div>
 <div class="vps-panel vps-table" style="margin-top:12px"><h3>Storico accessi e tentativi SSH</h3><table><thead><tr><th>Ultimo evento</th><th>Evento</th><th>IP</th><th>Località</th><th>Provider</th><th>Eventi</th><th>Stato</th></tr></thead><tbody id="vpsSecurityRows"><tr><td colspan="7">Caricamento...</td></tr></tbody></table></div>
</section>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js"></script>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
(()=>{const q=id=>document.getElementById(id),esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),bytes=n=>{n=Number(n||0);for(const u of ['B','KB','MB','GB','TB']){if(n<1024)return n.toFixed(u==='B'?0:1)+' '+u;n/=1024}return n.toFixed(1)+' PB'},duration=s=>{s=Number(s||0);const d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);return `${d}g ${h}h ${m}m`},state=v=>['active','healthy','ok'].includes(String(v).toLowerCase())?'vps-good':['failed','critical','inactive'].includes(String(v).toLowerCase())?'vps-critical':'vps-warning';let chart,map,layer;
function metric(prefix,data){q(prefix).textContent=Number(data.percent||0).toFixed(1)+'%';q(prefix+'Bar').style.width=Math.min(100,Number(data.percent||0))+'%'}
async function json(url){const r=await fetch(url,{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()}
async function refresh(){try{const d=await json('/admin/api/vps/overview'),r=d.resources;metric('vpsCpu',r.cpu);metric('vpsRam',r.memory);metric('vpsDisk',r.disk);q('vpsHost').textContent=`${d.host.name} · ${d.host.os} ${d.host.release}`;q('vpsUpdated').textContent='Aggiornato '+new Date(d.generated_at).toLocaleString('it-IT');q('vpsHealth').textContent=d.health==='healthy'?'REGOLARE':'ATTENZIONE';q('vpsHealth').className=state(d.health);q('vpsCpuMeta').textContent=`${r.cpu.cores} core · load ${r.cpu.load_average.join(' / ')}`;q('vpsRamMeta').textContent=`${bytes(r.memory.used_bytes)} / ${bytes(r.memory.total_bytes)}`;q('vpsDiskMeta').textContent=`${bytes(r.disk.used_bytes)} / ${bytes(r.disk.total_bytes)}`;q('vpsUptime').textContent=duration(d.host.uptime_seconds);q('vpsNetwork').textContent=`↑ ${bytes(r.network.sent_bytes)} · ↓ ${bytes(r.network.received_bytes)}`;q('vpsServices').innerHTML=d.services.map(s=>`<div class="vps-row"><div><b>${esc(s.name)}</b><div class="muted">${s.pid?'PID '+s.pid+' · ':''}${s.memory_bytes?bytes(s.memory_bytes):''}${s.restarts!=null?' · riavvii '+s.restarts:''}</div></div><span class="vps-badge ${state(s.state)}">${esc(s.state)}</span></div>`).join('');q('vpsAlerts').innerHTML=d.alerts.length?d.alerts.map(a=>`<div class="vps-alert ${esc(a.level)}"><b>${esc(a.title)}</b><div>${esc(a.detail)}</div><small>${esc(a.action)}</small></div>`).join(''):'<div class="vps-good">✓ Nessun problema rilevato</div>';const cert=Object.fromEntries(d.certificates.map(c=>[c.domain,c]));q('vpsWeb').innerHTML=d.endpoints.map(e=>{const host=new URL(e.url).hostname,c=cert[host]||{};return `<div class="vps-info"><b>${esc(host)}</b><div class="${e.ok?'vps-good':'vps-critical'}">${e.ok?'ONLINE':'ERRORE'} · ${esc(e.status)}</div><small>${e.latency_ms} ms · TLS ${c.days_remaining??'—'} giorni</small></div>`}).join('');const s=d.security;q('vpsSecurity').innerHTML=`<div class="vps-info"><small>Firewall UFW</small><div class="${s.ufw_active?'vps-good':'vps-critical'}"><b>${s.ufw_active?'ATTIVO':'NON ATTIVO'}</b></div></div><div class="vps-info"><small>Fail2ban</small><div class="${state(s.fail2ban)}"><b>${esc(s.fail2ban)}</b></div></div><div class="vps-info"><small>SSH falliti 24h</small><div><b>${s.ssh_failures_24h}</b></div></div>`;const b=d.backup||{};q('vpsBackup').innerHTML=`<div class="vps-info"><small>Ultimo backup</small><div class="${b.available?'vps-good':'vps-warning'}"><b>${b.available?b.age_hours+' ore fa':'Non disponibile'}</b></div><small>${b.available?b.files+' file · '+bytes(b.size_bytes):'Verificare percorso e permessi'}</small></div>`;q('vpsInventory').innerHTML=Object.entries(d.inventory).map(([k,v])=>`<div class="vps-info"><small>${esc(k)}</small><div><b>${esc(v)}</b></div></div>`).join('')}catch(e){q('vpsHealth').textContent='DATI NON DISPONIBILI';q('vpsHealth').className='vps-critical'}}
async function loadHistory(){try{const d=await json('/admin/api/vps/history?hours='+q('vpsHistoryRange').value),rows=d.samples;q('vpsHistoryEmpty').textContent=rows.length<2?'Lo storico si sta popolando automaticamente.':'';if(!window.Chart||!rows.length)return;if(chart)chart.destroy();chart=new Chart(q('vpsHistoryChart'),{type:'line',data:{labels:rows.map(x=>new Date(x.at).toLocaleString('it-IT',{day:'2-digit',hour:'2-digit',minute:'2-digit'})),datasets:[{label:'CPU %',data:rows.map(x=>x.cpu),borderColor:'#55d6e8',pointRadius:0},{label:'RAM %',data:rows.map(x=>x.memory),borderColor:'#a78bfa',pointRadius:0},{label:'Disco %',data:rows.map(x=>x.disk),borderColor:'#fbbd23',pointRadius:0}]},options:{scales:{y:{min:0,max:100,ticks:{color:'#b9c9d1'}},x:{ticks:{color:'#b9c9d1'}}},plugins:{legend:{labels:{color:'#fff'}}}}})}catch(e){q('vpsHistoryEmpty').textContent='Storico non disponibile'}}
function renderMap(rows){if(!window.L){q('vpsMapMeta').textContent='Mappa non disponibile';return}if(!map){map=L.map('vpsMap',{worldCopyJump:true,minZoom:2}).setView([20,10],2);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap'}).addTo(map);layer=L.layerGroup().addTo(map)}layer.clearLayers();const located=rows.filter(x=>Number.isFinite(Number(x.latitude))&&Number.isFinite(Number(x.longitude))),bounds=[];for(const x of located){const accepted=x.status==='autorizzato',size=Math.max(26,Math.min(54,24+Math.log10(Math.max(1,x.attempts))*9)),icon=L.divIcon({className:'',html:`<div class="vps-map-marker ${accepted?'accepted':''}" style="width:${size}px;height:${size}px">${x.attempts}</div>`,iconSize:[size,size]});L.marker([x.latitude,x.longitude],{icon}).bindPopup(`<b>${esc(x.ip)}</b><br>${esc(x.event)} · ${x.attempts}<br>${esc([x.city,x.region,x.country].filter(Boolean).join(', '))}<br>${esc(x.provider)}`).addTo(layer);bounds.push([x.latitude,x.longitude])}if(bounds.length)map.fitBounds(bounds,{padding:[30,30],maxZoom:5});q('vpsMapMeta').textContent=`${located.length} sorgenti geolocalizzate su ${rows.length}`;setTimeout(()=>map.invalidateSize(),50)}
async function loadSecurity(){try{const d=await json('/admin/api/vps/security/events?hours='+q('vpsSecurityRange').value);renderMap(d.sources);q('vpsSecurityRows').innerHTML=d.sources.length?d.sources.map(x=>`<tr><td>${esc(x.last_seen)}</td><td>${esc(x.event)}</td><td><code>${esc(x.ip)}</code></td><td>${esc([x.city,x.region,x.country].filter(Boolean).join(', ')||'Non disponibile')}</td><td>${esc(x.provider)}</td><td><b>${x.attempts}</b></td><td><span class="vps-badge ${x.status==='autorizzato'?'vps-good':'vps-critical'}">${esc(x.status)}</span></td></tr>`).join(''):'<tr><td colspan="7">Nessun evento rilevato</td></tr>'}catch(e){q('vpsSecurityRows').innerHTML='<tr><td colspan="7">Storico sicurezza non disponibile</td></tr>'}}
async function loadIncidents(){try{const d=await json('/admin/api/vps/incidents?limit=12');q('vpsIncidents').innerHTML=d.incidents.length?d.incidents.reverse().map(x=>`<div class="vps-row"><span class="${state(x.health)}">${esc((x.alerts||[]).map(a=>a.title).join(', '))}</span><small>${new Date(x.at).toLocaleString('it-IT')}</small></div>`).join(''):'<div class="muted">Nessun incidente registrato</div>'}catch(e){q('vpsIncidents').textContent='Non disponibile'}}
q('vpsHistoryRange').addEventListener('change',loadHistory);q('vpsSecurityRange').addEventListener('change',loadSecurity);refresh();loadHistory();loadSecurity();loadIncidents();setInterval(refresh,15000);setInterval(loadHistory,60000);setInterval(loadSecurity,60000);setInterval(loadIncidents,60000)})();
</script>"""
